    $reflection = new ReflectionClass($class);

    do {
        $attributes = $reflection->getAttributes(UsePolicy::class);

        if ($attributes !== []) {
            return $attributes[0]->newInstance()->class;
        }
    } while ($includeParents && $reflection = $reflection->getParentClass());

    return null;
