public function pusher(array $config)
{
    $guzzleClient = new GuzzleClient(
        array_merge(
            [
                'connect_timeout' => 10,
                'crypto_method' => STREAM_CRYPTO_METHOD_TLSv1_2_CLIENT,
                'timeout' => 30,
            ],
            $config['client_options'] ?? [],
        ),
    );

    $pusher = new Pusher(
        $config['key'],
        $config['secret'],
        $config['app_id'],
        $config['options'] ?? [],
        $guzzleClient,
    );

    if ($config['log'] ?? false) {
        $pusher->setLogger($this->app->make(LoggerInterface::class));
    }

    return $pusher;
}
