```php
public function generateAblySignature($channelName, $socketId, $userData = null)
{
    return hash_hmac(
        'sha256',
        sprintf('%s:%s%s', $socketId, $channelName, $userData ? ':'.json_encode($userData) : ''),
        $this->getPrivateToken(),
    );
}
