public function prune(DateTimeInterface $before)
{
    $query = $this->connection->table($this->table)
        ->whereNotNull('finished_at')
        ->where('finished_at', '<', $before->getTimestamp());

    $totalDeleted = 0;

    do {
        $deleted = $query->limit(1000)->delete();

        $totalDeleted += $deleted;
    } while ($deleted !== 0);

    return $totalDeleted;
}
