public static function join($array, $glue, $finalGlue = '')
{
    if ($finalGlue === '') {
        return implode($glue, $array);
    }

    if (count($array) === 0) {
        return '';
    }

    if (count($array) === 1) {
        return array_last($array);
    }

    $finalItem = array_pop($array);

    return implode($glue, $array).$finalGlue.$finalItem;
}
