public function median($key = null)
{
    $values = (isset($key) ? $this->pluck($key) : $this)
        ->reject(fn ($item) => is_null($item))
        ->sort()->values();

    $count = $values->count();

    if ($count === 0) {
        return;
    }

    $middle = intdiv($count, 2);

    if ($count % 2) {
        return $values->get($middle);
    }

    return $this->newInstance([
        $values->get($middle - 1), $values->get($middle),
    ])->average();
}
```

