public function mapToDictionary(callable $callback)
{
    $dictionary = [];

    foreach ($this->items as $key => $item) {
        $pair = $callback($item, $key);

        $key = key($pair);

        $value = reset($pair);

        if (! isset($dictionary[$key])) {
            $dictionary[$key] = [];
