    if ($job instanceof ShouldBeUnique) {
        return $this->dispatchUniqueJobToQueue($job, $queue, $connection);
    }

    $this->getDispatcher()->dispatch(
        $job->onConnection($connection)->onQueue($queue)
    );
}
