protected function loadMissingRelation(self $models, array $path)
{
    $relation = array_shift($path);

    $name = explode(':', key($relation))[0];

    if (is_string(reset($relation))) {
        $relation = reset($relation);
    }

    $models->filter(fn ($model) => ! is_null($model) && ! $model->relationLoaded($name))->load($relation);

    if (empty($path)) {
        return;
    }

    $models = $models->pluck($name)->filter();

    if ($models->first() instanceof BaseCollection) {
        $models = $models->collapse();
    }

    $models->groupBy(fn ($model) => $model::class)->each(
        fn ($models) => $this->loadMissingRelation(new static($models), $path)
    );
}
