        $pivotQuery = (new ($this->getPivotClass()))
            ->setTable($this->table)
            ->newQueryWithoutRelationships();

        $column($pivotQuery);

        $this->pivotWheres[] = [
            fn ($query) => $query->addNestedWhereQuery($pivotQuery->getQuery()),
            null,
