protected function setForeignAttributesForCreate(Model $model)
{
    $model->{$this->getForeignKeyName()} = $this->getParentKey();

    $model->{$this->getMorphType()} = $this->morphClass;

    foreach ($this->getQuery()->pendingAttributes as $key => $value) {
