public function sole($columns = ['*'])
{
    $result = $this->limit(2)->get($columns);

    $count = $result->count();

    if ($count === 0) {
        throw (new ModelNotFoundException)->setModel(get_class($this->related));
    }

    if ($count > 1) {
        throw new MultipleRecordsFoundException($count);
    }

    return $result->first();
}
