protected static function buildMorphMapFromModels(?array $models = null)
{
    if (is_null($models) || ! array_is_list($models)) {
        return $models;
    }

    return array_combine(array_map(function ($model) {
        return (new $model)->getTable();
    }, $models), $models);
}
