protected function getDatePrefix()
{
    $path = $this->currentMigrationPath;

    if ($path === null) {
        return date('Y_m_d_His');
    }

    $date = Date::now();

    while ($this->files->glob($path.'/'.$date->format('Y_m_d_His').'_*.php')) {
        $date = $date->addSecond();
    }

    return $date->format('Y_m_d_His');
}
