protected function resolveDatePeriodBounds(DatePeriod $period)
{
    [$start, $end] = [$period->getStartDate(), $period->getEndDate()];

    if ($end === null) {
        $end = clone $start;

        $recurrences = $period->getRecurrences();

        for ($i = 0; $i < $recurrences; $i++) {
            $end = $end->add($period->getDateInterval());
        }
    }

    return [$start, $end];
}
