```php
protected function pluckFromObjectColumn($queryResult, $column, $key)
{
    $results = [];

    if (is_null($key)) {
        foreach ($queryResult as $row) {
            $results[] = $row->$column;
        }
    } else {
        foreach ($queryResult as $row) {
            $results[$row->$key] = $row->$column;
        }
    }

    return new Collection($results);
}
