protected function parseJsonPathArrayKeys($attribute)
{
    if (preg_match('/(\[[^\]]+\])+$/', $attribute, $parts)) {
        $key = Str::beforeLast($attribute, $parts[0]);

        preg_match_all('/\[([^\]]+)\]/', $parts[0], $keys);

        return (new Collection([$key]))
            ->merge($keys[1])
            ->diff('')
            ->values()
            ->all();
    }

    return [$attribute];
}
