        if (empty(array_intersect([$table['name'], $table['schema_qualified_name']], $excludedTables))) {
            $tables[] = $table['schema_qualified_name'];
        }
    }

    if (empty($tables)) {
        return;
    }

    $this->connection->statement(
        $this->grammar->compileDropAllTables($tables)
    );
}
