public function sharedGet($path)
{
    $contents = '';

    $handle = fopen($path, 'rb');

    if ($handle) {
        try {
            if (flock($handle, LOCK_SH)) {
                clearstatcache(true, $path);

                $contents = stream_get_contents($handle);

                flock($handle, LOCK_UN);
            }
        } finally {
            fclose($handle);
        }
    }

    return $contents;
}
