        }
    }

    $app->make('config')->set(
        'app.providers',
        array_merge(
            $app->make('config')->get('app.providers') ?? ServiceProvider::defaultProviders()->toArray(),
            static::$merge,
            array_values($packageProviders ?? []),
        ),
    );
}
