    return $prefix.array_reduce(array_keys($meta), function ($carry, $key) use ($meta) {
        try {
            return $carry.$key.': '.match ($meta[$key]) {
                true => 'true',
                false => 'false',
                default => $meta[$key],
            }."\n";
        } catch (Throwable) {
            return $carry;
        }
    }, '');
}
