```php
protected function argType(mixed $argument, string|int $name): string|array
{
    $type = match (gettype($argument)) {
        'NULL' => 'null',
        'string' => 'string',
        'boolean' => 'bool',
        'integer' => 'int',
        'double' => 'float',
        'array' => 'array',
        'object' => $argument::class,
        'resource' => 'resource',
        'resource (closed)' => 'resource(closed)',
        default => '[unknown]',
    };

    return is_int($name) ? $type : [$name, $type];
}
