public function dumpWithSource(Data $data)
{
    if ($this->dumping) {
        $this->dump($data);

        return;
    }

    $this->dumping = true;

    $output = (string) $this->dump($data, true);
    $lines = explode("\n", $output);

    $lines[array_key_last($lines) - 1] .= $this->getDumpSourceContent();

    $this->output->write(implode("\n", $lines));

    $this->dumping = false;
}
