    if (windows_os()) {
        $separator = '\\';
    }

    $path = $this->viewPath(
        str_replace('.', $separator, $this->getView()).'.blade.php'
    );

    if ($this->files->exists($path)) {
        return $this->components->error(sprintf('%s [%s] already exists.', 'Markdown view', $path));
