    $this->files->ensureDirectoryExists(dirname($path));

    $this->files->put($path, file_get_contents(__DIR__.'/stubs/markdown.stub'));

    $this->components->info(sprintf('%s [%s] created successfully.', 'Markdown view', $path));
}
