/** Get the URI for the given route, including any binding fields. */
protected function resolveUri(Route $route)
{
    $uri = $route->uri();

    foreach ($route->bindingFields() as $parameter => $field) {
        $uri = str_replace("{{$parameter}}", "{{$parameter}:{$field}}", $uri);
    }

    return $uri;
}
