        return false;
    }

    $contents = preg_replace(
        ['/\{{ namespace \}}/', '/\{{ class \}}/', '/\{{ name \}}/'],
        [$this->testNamespace(), $this->testClassName(), $this->testViewName()],
        File::get($this->getTestStub()),
