protected function renderViaCallbacks($request, Throwable $e)
{
    foreach ($this->renderCallbacks as $renderCallback) {
        foreach ($this->firstClosureParameterTypes($renderCallback) as $type) {
            if (is_a($e, $type)) {
                $response = $renderCallback($e, $request);

                if (! is_null($response)) {
                    return $response;
                }
            }
        }
    }
}
