protected function dotInputKeys(array $input, string $prefix = ''): array
{
    $keys = [];

    foreach ($input as $key => $value) {
        $key = $prefix.str_replace('.', '\.', (string) $key);

        if (is_array($value) && $value !== []) {
            $keys = array_merge($keys, $this->dotInputKeys($value, $key.'.'));
        } else {
            $keys[] = $key;
        }
    }

    return $keys;
}
