public function attach($name, $contents = '', $filename = null, array $headers = [])
{
    if (is_array($name)) {
        foreach ($name as $file) {
            $this->attach(...$file);
        }

        return $this;
    }

    $this->asMultipart();

    $file = [
        'name' => $name,
        'contents' => $contents,
        'headers' => $headers,
    ];

    if ($filename !== null) {
        $file['filename'] = $filename;
    }

    $this->pendingFiles[] = $file;

    return $this;
}
