protected function acceptHeaderIsBroad($accept)
{
    if ($accept === null || trim($accept) === '') {
        return true;
    }

    foreach (explode(',', $accept) as $value) {
        $value = strtolower(trim($value));

        if ($value === '') {
            continue;
        }

        $pos = strpos($value, ';');

        if ($pos !== false) {
            $value = trim(substr($value, 0, $pos));
        }

        if (! in_array($value, ['*/*', 'application/*'], true)) {
            return false;
        }
    }

    return true;
}
