/** Get the file extension based on the MIME type. */
public function extension(): string
{
    return match ($this->mimeType()) {
        'image/jpeg' => 'jpg',
        'image/png' => 'png',
        'image/gif' => 'gif',
        'image/webp' => 'webp',
        'image/avif', 'image/x-avif' => 'avif',
        'image/heic', 'image/x-heic', 'image/heif' => 'heic',
        'image/bmp' => 'bmp',
        'image/svg+xml' => 'svg',
        'image/tiff' => 'tiff',
        default => 'bin',
    };
}
