```php
private function formatActualRecipients($recipients)
{
    if (empty($recipients)) {
        return 'none';
    }

    return (new Collection($recipients))->map(function ($recipient) {
        $formatted = $recipient['address'];
        if (! empty($recipient['name'])) {
            $formatted .= ' ('.$recipient['name'].')';
        }

        return $formatted;
    })->implode(', ');
}
