    if (! empty($this->replyTo['address'])) {
        $message->replyTo($this->replyTo['address'], $this->replyTo['name']);
    }

    if (! empty($this->returnPath['address'])) {
        $message->returnPath($this->returnPath['address']);
    }

    return $message;
}
