    if (! str_contains($part, 'Content-Transfer-Encoding: quoted-printable')) {
        return $part;
    }

    [$headers, $content] = explode("\r\n\r\n", $part, 2);

    return implode("\r\n\r\n", [
        $headers,
        quoted_printable_decode($content),
    ]);
}
