    if (! $payload) {
        return null;
    }

    if (! isset($payload['data']['command'])) {
        return $payload['job'] ?? null;
    }

    if (! empty($payload['displayName']) && is_string($payload['displayName'])) {
        return $payload['displayName'];
    }

    return $this->matchJobName($payload);
}
