            'timestamp' => $this->now()->format('Y-m-d\TH:i:s.uP'),
        ]));

        return;
    }

    $this->output->writeln(sprintf(
        '  <fg=gray>%s</> Worker <fg=yellow;options=bold>STOPPED</> <fg=gray>%s</>',
        $this->now()->format('Y-m-d H:i:s'),
        $event->reason->description(),
    ));
}
