            if ($node === null && empty($remainingMasters)) {
                return [$initialCursor, $result];
            }

            return ['laravel:'.base64_encode(json_encode([
                $scanned, $node, $cursor, $initialCursor,
            ], JSON_THROW_ON_ERROR)), $result];
        }

        if ($node !== null) {
            return ['laravel:'.base64_encode(json_encode([
                $scanned, $node, $cursor, $initialCursor,
            ], JSON_THROW_ON_ERROR)), []];
        }
    }
}
