protected function matchAgainstRoutes(array $routes, $request, $includingMethod = true)
{
    $fallbackRoute = null;

    foreach ($routes as $route) {
        if ($route->matches($request, $includingMethod)) {
            if ($route->isFallback) {
                $fallbackRoute ??= $route;

                continue;
            }

            return $route;
        }
    }

    return $fallbackRoute;
}
