protected function middlewareNames($middleware)
{
    $stripped = head(explode(':', $middleware));

    yield $stripped;

    $interfaces = @class_implements($stripped);

    if ($interfaces !== false) {
        foreach ($interfaces as $interface) {
            yield $interface;
        }
    }

    $parents = @class_parents($stripped);

    if ($parents !== false) {
        foreach ($parents as $parent) {
            yield $parent;
        }
    }
}
