    int $years = 0,
    int $months = 0,
    int $weeks = 0,
    int $days = 0,
    int $hours = 0,
    int $minutes = 0,
    int $seconds = 0,
    int $microseconds = 0,
    ?bool $overflow = null
): static {
    return $this->sub('years', $years, $overflow)
        ->sub('months', $months, $overflow)
        ->sub("
            $weeks weeks $days days
            $hours hours $minutes minutes $seconds seconds $microseconds microseconds
        ");
}
