public function validateDateFormat($attribute, $value, $parameters)
{
    $this->requireParameterCount(1, $parameters, 'date_format');

    if (! is_string($value) && ! is_numeric($value)) {
        return false;
    }

    foreach ($parameters as $format) {
        try {
