protected function compare($first, $second, $operator)
{
    return match ($operator) {
        '<' => $first < $second,
        '>' => $first > $second,
        '<=' => $first <= $second,
        '>=' => $first >= $second,
        '=' => ($first === $second) || ($first == $second && ! is_null($first) && ! is_null($second)),
        default => throw new InvalidArgumentException,
    };
}
