```php
protected function hasEvenNumberOfParentheses(string $expression)
{
    try {
        $tokens = token_get_all('<?php '.$expression);
    } catch (ParseError) {
        return false;
    }

    if (Arr::last($tokens) !== ')') {
        return false;
    }

    $opening = 0;
    $closing = 0;

    foreach ($tokens as $token) {
        if ($token === ')') {
            $closing++;
        } elseif ($token === '(') {
            $opening++;
        }
    }

    return $opening === $closing;
}
