protected function escapeSingleQuotesOutsideOfPhpBlocks(string $value)
{
    return (new Collection(token_get_all($value)))->map(function ($token) {
        if (! is_array($token)) {
            return $token;
        }

        return $token[0] === T_INLINE_HTML
            ? str_replace("'", "\\'", $token[1])
            : $token[1];
    })->implode('');
}
