/** Don't allow Mockery's InvalidCountException to be reported. Mocks setup in PendingCommand cause PHPUnit tearDown() to later throw the exception. */
protected function ignoringMockOnceExceptions(callable $callback)
{
    try {
        $callback();
    } finally {
        try {
            Mockery::close();
        } catch (InvalidCountException) {
            // Ignore mock exception from PendingCommand::expectsOutput().
        }
    }
}
